   440	  /* Based on Quick Search algorithm (Boyer-Moore-Horspool algorithm) */
   441	
   442	  ptrdiff_t qstable[1 << CHAR_BIT];
   443	
   444	  /* Preprocessing */
   445	  {
   446	    mrb_int i;
   447	
   448	    for (i = 0; i < 1 << CHAR_BIT; i ++) {
   449	      qstable[i] = slen;
   450	    }
   451	    for (i = 0; i < slen; i ++) {
   452	      qstable[(unsigned char)s[i]] = slen - (i + 1);
   453	    }
   454	  }
   455	
   456	  /* Searching */
   457	  while (p < pend && pend - p >= slen) {
   458	    const char *pivot;
   459	
   460	    if (memcmp(p, s, slen) == 0) {
   461	      return off;
   462	    }
   463	
   464	    pivot = p + qstable[(unsigned char)p[slen - 1]];
   465	    if (pivot > pend || pivot < p /* overflowed */) { return -1; }
